### Подключение MongoDB

Согласно документации MongoDB предпочтительно создавать один экземпляр MongoClient и использовать его внутри остальных частей приложения, к тому же MongoClient потокобезопасный. То есть по сути нам надо определить объект синглтон:

```c#
using MongoDB.Bson;
using MongoDB.Driver;

var builder = WebApplication.CreateBuilder(args);

// определяем MongoClient как синглтон
builder.Services.AddSingleton(new MongoClient("mongodb://localhost:27017"));

var app = builder.Build();

app.MapGet("/", async (MongoClient client) =>     // получаем MongoClient через DI
{
    var db = client.GetDatabase("test");    // обращаемся к базе данных
    var collection = db.GetCollection<BsonDocument>("users"); // получаем коллекцию users
    // для теста добавляем начальные данные, если коллекция пуста
    if (await collection.CountDocumentsAsync("{}") == 0)
    {
        await collection.InsertManyAsync(new List<BsonDocument>
        {
            new BsonDocument{ { "Name", "Tom" },{"Age", 22}},
            new BsonDocument{ { "Name", "Bob" },{"Age", 42}}
        });
    }
    var users =  await collection.Find("{}").ToListAsync();
    return users.ToJson();  // отправляем клиенту все документы из коллекции
});
app.Run();
```

С помощью метода `builder.Services.AddSingleton()` добавляем MongoClient в сервисы приложения, и затем мы можем получить данный сервис как и любой другой через стандартный способы получения зависимостей в ASP.NET Core. В данном случае получаем MongoClient получаем через обработчик конечной точки. Затем внутри обработчика уже можно обращаться к базе данных и ее коллекциям и производить операции с данными. Так, здесь для теста просто отправляем все документы из коллекции:

![подключение к базе данных mongodb в приложении asp.net core на c#](/uploads/course-lectures/de548440983223ee31632cf8b531424056b6a53c.png)

Но также стоит отметить, что согласно документации объект IMongoDatabase также потокобезопасный и может применяться как синглтон. Поэтому, если нам необходимо обращаться к одной и той же базе данных, то мы можем также определить объект IMongoDatabase как синглтон и передавать его через механизм DI в приложение:

```c#
using MongoDB.Bson;
using MongoDB.Driver;

var builder = WebApplication.CreateBuilder(args);

// определяем IMongoDatabase как синглтон
builder.Services.AddSingleton(new MongoClient("mongodb://localhost:27017").GetDatabase("test"));

var app = builder.Build();

app.MapGet("/", async (IMongoDatabase db) =>     // получаем IMongoDatabase - базу данных "test" через DI
{
    var collection = db.GetCollection<BsonDocument>("users"); // получаем коллекцию users
    // для теста добавляем начальные данные, если коллекция пуста
    if (await collection.CountDocumentsAsync("{}") == 0)
    {
        await collection.InsertManyAsync(new List<BsonDocument>
        {
            new BsonDocument{ { "Name", "Tom" },{"Age", 38}},
            new BsonDocument{ { "Name", "Bob" },{"Age", 42}}
        });
    }
    var users =  await collection.Find("{}").ToListAsync();
    return users.ToJson();  // отправляем клиенту все документы из коллекции
});
app.Run();
```

Определим простейший Web API, который будет выполнять все основные операции с данными в бд MongoDB.



### Серверная часть



В файле **Program.cs** определим код веб-приложения:



```c#

using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using MongoDB.Driver;

var client = new MongoClient("mongodb://localhost:27017");  // определяем клиент
var db = client.GetDatabase("test");    // определяем объект базы данных
var collectionName = "users";   // имя коллекции

var builder = WebApplication.CreateBuilder(args);

var app = builder.Build();

app.UseDefaultFiles();
app.UseStaticFiles();

app.MapGet("/api/users", () =>
    db.GetCollection<Person>(collectionName).Find("{}").ToListAsync());

app.MapGet("/api/users/{id}", async (string id) =>
{
    var user = await db.GetCollection<Person>(collectionName)
        .Find(p=>p.Id == id)
        .FirstOrDefaultAsync();

    // если не найден, отправляем статусный код и сообщение об ошибке
    if (user == null) return Results.NotFound(new { message = "Пользователь не найден" });

    // если пользователь найден, отправляем его
    return Results.Json(user);
});
app.MapDelete("/api/users/{id}", async (string id) =>
{
    var user = await db.GetCollection<Person>(collectionName).FindOneAndDeleteAsync(p=>p.Id==id);
    // если не найден, отправляем статусный код и сообщение об ошибке
    if (user is null) return Results.NotFound(new { message = "Пользователь не найден" });
    return Results.Json(user);
});

app.MapPost("/api/users", async (Person user) => {

    // добавляем пользователя в список
    await db.GetCollection<Person>(collectionName).InsertOneAsync(user);
    return user;
});

app.MapPut("/api/users", async (Person userData) => {

    var user = await db.GetCollection<Person>(collectionName)
        .FindOneAndReplaceAsync(p => p.Id == userData.Id, userData, new() { ReturnDocument = ReturnDocument.After });
    if (user == null) 
        return Results.NotFound(new { message = "Пользователь не найден" });
    return Results.Json(user);
});

app.Run();

public class Person
{
    [BsonRepresentation(BsonType.ObjectId)]
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public int Age { get; set; }
}
```



Разберем в общих чертах этот код. Вначале создается клиент MongoClient и объект IMongoDatabase, который будет представлять базу данных "test":



```javascript

var client = new MongoClient("mongodb://localhost:27017");  // определяем клиент
var db = client.GetDatabase("test");    // определяем объект базы данных
var collectionName = "users";   // имя коллекции
```



Поскольку для простоты весь код веб-приложения определен в одном файле Program.cs, то нет смысла задействовать встроенную систему внедрения зависимостей, и добавлять MongoClient и IMongoDatabase в приложение в виде сервисов. Поэтому проще их определить в виде глобальных переменных.



Для представления данных, которые будут храниться в таблице "users", в конце файла определен класс Person.



Далее после создания объекта WebApplication подключаем функциональность статических файлов:



```c#

app.UseDefaultFiles();
app.UseStaticFiles();
```



Затем с помощью методов **MapGet/MapPost/MapPut/MapDelete** определяется набор конечных точек, которые будут обрабатывать разные типы запросов.



Вначале добавляется конечная точка, которая обрабатывает запрос типа GET по маршруту "api/users":



```c#

app.MapGet("/api/users", () =>
    db.GetCollection<Person>(collectionName).Find("{}").ToListAsync());
```



Запрос GET предполагает получение объектов, и в данном случае отправляем все полученные из коллекции users объекты Person.



Когда клиент обращается к приложению для получения одного объекта по id в запрос типа GET по адресу "api/users/{id}", то срабатывает другая конечная точка:



```c#

app.MapGet("/api/users/{id}", async (string id) =>
{
    var user = await db.GetCollection<Person>(collectionName)
        .Find(p=>p.Id == id)
        .FirstOrDefaultAsync();

    // если не найден, отправляем статусный код и сообщение об ошибке
    if (user == null) return Results.NotFound(new { message = "Пользователь не найден" });

    // если пользователь найден, отправляем его
    return Results.Json(user);
});
```



Здесь через параметр id получаем из пути запроса идентификатор объекта Person и по этому идентификатору ищем нужный документ в коллекции users. Если объект по Id не был найден, то возвращаем с помощью метода `Results.NotFound()` статусный код 404 с некоторым сообщением в формате JSON. Если объект найден, то с помощью метода `Results.Json()` отправляет найденный объект клиенту.



При получении запроса типа DELETE по маршруту "/api/users/{id}" срабатывает другая конечная точка:



```c#

app.MapDelete("/api/users/{id}", async (string id) =>
{
    var user = await db.GetCollection<Person>(collectionName).FindOneAndDeleteAsync(p=>p.Id==id);
    // если не найден, отправляем статусный код и сообщение об ошибке
    if (user is null) return Results.NotFound(new { message = "Пользователь не найден" });
    return Results.Json(user);
});
```



С помощью метода `FindOneAndDeleteAsync()` удаляем объект по Id и возвращаем его. Если документ по Id не найден, отправляет статусный код 404. Если же объект найден, то он удаляется из коллекции и посылается клиенту.



При получении запроса с методом POST по адресу "/api/users" срабатывает следующая конечная точка:



```c#

app.MapPost("/api/users", async (Person user) => {

    // добавляем пользователя в список
    await db.GetCollection<Person>(collectionName).InsertOneAsync(user);
    return user;
});
```



Запрос типа POST предполагает передачу приложению отправляемых данных. Причем мы ожидаем, что клиент отправит данные, которые соответствуют определению типа Person. И поэтому инфраструктура ASP.NET Core сможет автоматически собрать из них объект Person. И этот объект мы сможем получить в качестве параметра в обработчике конечной точки и с помощью метода `InsertOneAsync()` добавить в коллекцию "users".



Если приложению приходит PUT-запрос по адресу "/api/users", то аналогичным образом получаем отправленные клиентом данные в виде объекта Person и с помощью метода `FindOneAndReplaceAsync()` пытаемся найти подобный документ в коллекции users и заменить его новым:



```c#

app.MapPut("/api/users", async (Person userData) => {

    var user = await db.GetCollection<Person>(collectionName)
        .FindOneAndReplaceAsync(p => p.Id == userData.Id, userData, new() { ReturnDocument = ReturnDocument.After });
    if (user == null) 
        return Results.NotFound(new { message = "Пользователь не найден" });
    return Results.Json(user);
});
```



Чтобы метод `FindOneAndReplaceAsync()` возвратил обновленный документ, в метод через третий параметр передается объект `new FindOneAndReplaceOptions { ReturnDocument = ReturnDocument.After }`. Если документ в коллекции не найден, отправляем статусный код 404. Если документ найден, то отправляем обратно клиенту обновленные данные.



Стоит отметить, что в данном случае предполагается, что структура документов в коллекции совпадает с определением класса Person. Однако в реальности в коллекции документ может иметь какие-то дополнительные поля. И в этом случае будет более оптимально не полная замена, а точечное обновление отдельных полей с помощью метода `FindOneAndUpdateAsync()`.



Таким образом, мы определили простейший API. Теперь добавим код клиента.



